"""Build the static SilentForge website. No package installation required."""
from pathlib import Path
import re, shutil, json, html

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'dist'
OUT.mkdir(exist_ok=True)
shutil.copytree(ROOT / 'assets', OUT / 'assets', dirs_exist_ok=True)
ORIGIN = 'https://silentforge-drones.treverbarney.chatgpt.site'
pages = {}

def add(path, title, description, body):
    pages[path] = (title, description, body)

def intro(kicker, title, text):
    return f'<section class="intro shell"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{text}</p></section>'

def article(kicker, title, text, content):
    return intro(kicker, title, text) + f'<article class="shell"><div class="prose">{content}</div></article>'

drone = '''<svg viewBox="0 0 600 460" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrated mini quadcopter concept with four propeller guards"><defs><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#657671"/><stop offset="1" stop-color="#1b2828"/></linearGradient></defs><g transform="translate(300 230) rotate(-25) scale(1 .76)"><path d="M-155-125 155 125M155-125-155 125" stroke="#132020" stroke-width="47"/><path d="M-155-125 155 125M155-125-155 125" stroke="url(#metal)" stroke-width="30"/><g fill="#0b1516" stroke="#6e8b7d" stroke-width="9"><circle cx="-155" cy="-125" r="78"/><circle cx="155" cy="-125" r="78"/><circle cx="-155" cy="125" r="78"/><circle cx="155" cy="125" r="78"/></g><g fill="#b9f27b" opacity=".85"><ellipse cx="-155" cy="-125" rx="61" ry="12" transform="rotate(25 -155 -125)"/><ellipse cx="155" cy="-125" rx="61" ry="12" transform="rotate(-30 155 -125)"/><ellipse cx="-155" cy="125" rx="61" ry="12" transform="rotate(-30 -155 125)"/><ellipse cx="155" cy="125" rx="61" ry="12" transform="rotate(25 155 125)"/></g><rect x="-66" y="-85" width="132" height="170" rx="35" fill="url(#metal)" stroke="#95a99a" stroke-width="2"/><rect x="-46" y="-60" width="92" height="115" rx="18" fill="#1a2928"/><path d="M-30-40H30M-30-25H30M-30-10H30M-30 5H30M-30 20H30" stroke="#40564b" stroke-width="5"/><rect x="-19" y="-84" width="38" height="23" rx="7" fill="#090f10" stroke="#759385"/><circle cy="-74" r="7" fill="#b9f27b"/><text x="0" y="75" text-anchor="middle" fill="#b9f27b" font-family="monospace" font-size="11">SF / 01</text></g></svg>'''

add('/', 'Custom mini drones, thoughtfully configured', 'Explore custom mini drone concepts, 3D printed frames, sensors and AI options. Plan a build with SilentForge.', f'''<div class="shell"><section class="hero"><div><span class="status">Custom mini drone workshop · In development</span><h1>Small airframe.<br>Big possibilities.</h1><p>Shape a mini drone around your idea. Explore frames, cameras, sensors and compute, then turn your configuration into a conversation.</p><div class="actions"><a class="button" href="/configure/">Configure your build <span aria-hidden="true">↗</span></a><a class="button secondary" href="/how-it-works/">Explore the process</a></div><p class="small">Concept planning now. Every build needs engineering review.</p></div><div class="hero-art">{drone}<div class="art-caption"><span>SF—01 / CONCEPT STUDY</span><span>NOT A PRODUCTION MODEL</span></div></div></section><div class="band"><div><strong>Made around your idea</strong><span>Explore custom frames and mounts</span></div><div><strong>See the trade-offs</strong><span>Weight, energy and budget estimates</span></div><div><strong>Review before committing</strong><span>No payment collected on this site</span></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">A starting point, shaped by you</span><h2>What do you want to build?</h2></div><p>A compact platform for learning, experimenting and exploring ideas. Choose a direction and work through the practical details.</p></div><div class="grid"><article class="card"><span class="number">01 / AIRFRAME</span><h3>Make room for your idea.</h3><p>Explore open, ducted and enclosed frame concepts, with options for custom printed bodies and sensor mounts.</p><a href="/configure/">Explore frames ↗</a></article><article class="card"><span class="number">02 / PAYLOAD</span><h3>Give it a new perspective.</h3><p>Compare camera, navigation and ranging concepts. Each addition changes weight, power and integration work.</p><a href="/technology/">Understand the options ↗</a></article><article class="card"><span class="number">03 / COMPUTE</span><h3>Build beyond the airframe.</h3><p>Consider onboard or remote processing. Start with the task, then review hardware, software and connectivity together.</p><a href="/technology/#compute">Explore compute ↗</a></article></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">From idea to engineering review</span><h2>A clear path forward.</h2></div><a href="/how-it-works/">How the process works ↗</a></div><div class="grid"><article><span class="eyebrow">01 / Explore</span><h3>Choose your starting point.</h3><p>Use the builder to compare options and record your goals.</p></article><article><span class="eyebrow">02 / Review</span><h3>Work through the details.</h3><p>Discuss compatibility, intended use, constraints and what needs testing.</p></article><article><span class="eyebrow">03 / Agree</span><h3>Set a scope before a build.</h3><p>Any future order needs a written specification, price and delivery terms.</p></article></div></section></div>''')

add('/how-it-works/', 'How a custom drone build works', 'From initial configuration to compatibility review and a written build scope.', article('The process', 'Start with the mission.', 'A useful drone starts with a clear purpose. The configurator helps make that first conversation concrete.', '''<h2>01. Tell us what you are exploring</h2><p>Describe where you intend to fly, your experience level, what you want to learn or capture, and your budget. Include size, payload and operating environment constraints.</p><h2>02. Explore a configuration</h2><p>Choose a frame, propeller concept, battery, sensor and compute option. Download the resulting brief or bring it into a build inquiry. Values are planning assumptions, not measured specifications.</p><h2>03. Review feasibility</h2><p>Before a build can be agreed, review motor and propeller pairing, thrust, battery discharge rating, voltage, mounting, cooling, radio control and software. An option appearing in the builder does not establish compatibility.</p><h2>04. Agree the work in writing</h2><p>Confirm the bill of materials, engineering work, testing, price, delivery timing and support terms before placing any future order. Online purchasing is not available at this stage.</p><h2>05. Define testing and handover</h2><p>A build scope should identify the checks and documentation needed before flight, including controls, failsafe behavior, battery handling and operating limitations.</p><div class="actions"><a class="button" href="/configure/">Start a configuration</a><a class="button secondary" href="/contact/">Discuss an idea</a></div>'''))

add('/technology/', 'Frames, sensors and AI options', 'Understand the engineering trade-offs behind the mini drone configurator.', article('Design notes', 'Every gram has a job.', 'Think of the builder as an exploration tool. A complete aircraft needs a matched, tested system.', '''<h2>Airframes and printed parts</h2><p>Open, ducted and enclosed body concepts offer different packaging possibilities. Material, print orientation, geometry and mounting design all need review. A rendered enclosure does not establish impact protection or weather resistance.</p><h2>Noise is a design target</h2><p>SilentForge is the project name. No sound-level measurement or noise reduction claim is available for these concepts. Propeller geometry, motor speed, loading and the operating environment all need to be evaluated.</p><h2>Battery and flight estimates</h2><p>The builder uses nominal battery energy and an illustrative hover model: usable energy = 80% of nominal watt-hours; estimated power = mass ÷ 7 grams per watt + compute power. Estimated hover minutes = usable energy ÷ estimated power × 60.</p><p>This model does not validate propulsion, takeoff weight, flight range, battery health, weather effects or payload compatibility. It is not a flight specification or a safe operating time.</p><h2>Sensors and cameras</h2><p>Camera, ranging and navigation entries represent component classes. A named component is an example to investigate, not a confirmed supplier, included item or endorsement. Mounting, interfaces and software support need separate review.</p><h2 id="compute">Onboard and remote compute</h2><p>Onboard processing adds mass, power demand and cooling needs. An accelerator also requires a compatible host and software. Remote processing requires a data connection and introduces latency and privacy considerations.</p><p>Selecting AI does not provide autonomous flight, obstacle avoidance or any trained model. Software scope and safe operating behavior must be defined and tested separately.</p><h2>What the cost estimate includes</h2><p>The inherited component allowances are shown with a separately itemized 30% planning margin. They are not current supplier prices and exclude engineering labor, a complete propulsion and radio system, chargers, shipping and taxes. Request a reviewed quote for any actual project.</p><a class="button" href="/configure/">Explore the configurator</a>'''))

add('/about/', 'About SilentForge', 'A mini drone project by Trever Barney, exploring hardware, CAD and software together.', article('About SilentForge', 'Built around curiosity.', 'A project by Trever Barney, bringing custom drone ideas into a more practical conversation.', '''<h2>Hardware and software, considered together</h2><p>My work spans programming, AI integration, robotics and CAD. SilentForge is an early-stage project for exploring how a small airframe, sensors and software might fit a particular idea.</p><p>The starting point is a configurator that makes trade-offs visible. It is a planning tool, and the next step is a review of what the actual aircraft would require.</p><h2>Clear about the stage</h2><p>SilentForge is in development. There is no production catalog, verified performance dataset or online ordering service at this stage. The illustrated drones and 3D previews are concepts.</p><h2>Have a useful idea?</h2><p>I am interested in the problem you are trying to solve, what you have already tried and what a useful result would look like.</p><div class="actions"><a class="button" href="/contact/">Contact Trever</a><a class="button secondary" href="https://www.barneyglobal.com">Visit Barney Global</a></div>'''))

faq = [
('Can I buy a drone here?', 'Online ordering and payments are not available. Use the configurator to prepare a brief, then contact Trever to discuss feasibility. No order is created by configuring a build.'),
('Are these drones silent?', 'No measured noise data is available. SilentForge is a project name; quieter operation is a design goal that would require testing.'),
('Are the prices and flight times guaranteed?', 'Prices and masses are itemized planning allowances, not supplier quotes or tested specifications. Hover time requires user-entered total aircraft power; it is calculated from usable battery energy and remains an estimate. See Technology for formulas and exclusions.'),
('Will every combination work?', 'No. The builder flags voltage, prop diameter, frame payload-envelope and radio mismatches, plus invalid inputs and tested thrust/current conflicts. Passing these planning rules does not certify physical fit or flight readiness. A build needs engineering review.'),
('Can I request a custom frame or software?', 'Yes, describe the idea in a build inquiry. Scope, feasibility, ownership of deliverables and pricing must be agreed before any work starts.'),
('Does choosing AI enable autonomous flight?', 'No. A compute option does not include an autonomous flight system, trained model or safety validation. Software requires a separate engineering scope.'),
('Do you ship internationally?', 'Shipping regions and delivery times have not been established. Availability and any battery transport restrictions must be confirmed in a written quote.'),
('Where do I get help?', 'Email trever@barneyglobal.com with your configuration or question. Do not send passwords, payment details or sensitive location information.'),
('Is my configuration saved?', 'The builder stores the selected options, optional performance inputs and your notes in this browser so you can continue to the request page. You can clear that saved configuration. Downloaded files stay on your device.')]
add('/faq/', 'Frequently asked questions', 'Answers about configurations, estimates, ordering, custom work and support.', intro('Help & support', 'Good questions.<br>Clear answers.', 'A few things to know before you start.') + '<div class="shell prose">' + ''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in faq) + '<div class="actions"><a class="button" href="/contact/">Ask another question</a></div></div>')

add('/contact/', 'Contact and build inquiries', 'Discuss a custom drone concept or ask a support question with Trever Barney.', intro('Contact', 'Tell me what you have in mind.', 'A clear brief is the best starting point. Include your goal, budget, experience and operating environment.') + '''<div class="shell request-layout"><form id="inquiry"><div class="form-row"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" maxlength="100" required></div><div class="form-row"><label for="email">Your email</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required></div><div class="form-row"><label for="topic">What can I help with?</label><select id="topic" name="topic"><option>Build inquiry</option><option>Custom frame or software</option><option>Support question</option><option>Other</option></select></div><div class="form-row"><label for="message">Your project or question</label><textarea id="message" name="message" maxlength="4000" required></textarea></div><p class="small">This form prepares an email in your mail app. Nothing is sent until you send it there. Please review our <a href="/privacy/">privacy notice</a>.</p><button class="button" type="submit">Prepare email ↗</button><p id="email-status" role="status"></p><a id="email-fallback" class="hidden" href="mailto:trever@barneyglobal.com">Open the prepared email</a></form><aside><div class="card"><span class="eyebrow">Direct contact</span><h2>Talk to Trever.</h2><a href="mailto:trever@barneyglobal.com">trever@barneyglobal.com</a><p>For project inquiries and support. Response times and availability have not been established.</p></div><div class="card"><h2>Your build brief</h2><pre id="brief">No saved configuration. You can still send a general inquiry.</pre><button id="clear-build" class="button secondary" type="button">Clear saved build</button><p class="small">Saved only in this browser. <a href="/configure/">Edit configuration</a>.</p></div></aside></div>''')

add('/safety/', 'Safety and responsible use', 'Planning considerations and official resources for responsible drone operation.', article('Before you fly', 'Build thoughtfully.<br>Fly responsibly.', 'A configurator cannot establish airworthiness or permission to fly.', '''<h2>Engineering review comes first</h2><p>Do not treat a preview, estimated flight time or selected component combination as a flight-ready specification. Obtain a competent review of the assembled system and its operating limits.</p><h2>Propellers and batteries</h2><p>Follow component manufacturers’ instructions. Remove propellers for bench setup where required by the equipment instructions. Use a compatible charger and follow the battery supplier’s handling, charging and disposal guidance.</p><h2>Know the operating environment</h2><p>Plan around people, property, obstacles and weather. A ducted concept is not a guarantee of safe contact, and an enclosed concept is not a weather rating. No obstacle-avoidance capability is established by this site.</p><h2>Check current official requirements</h2><p>Requirements depend on your aircraft, location and intended use. For the United States, start with the <a href="https://www.faa.gov/uas">FAA drone resources</a> and <a href="https://www.faa.gov/uas/getting_started/b4ufly">official airspace awareness resources</a>. Outside the US, consult your aviation authority. These links are starting points, not an assessment of your flight.</p><h2>Respect privacy</h2><p>Consider where cameras and other sensors point, what they collect and how that data is shared. Define data handling before adding remote processing or recording.</p>'''))

add('/shipping-returns/', 'Ordering, shipping and returns', 'The current ordering status and what must be agreed before a future drone build.', article('Order information', 'Agree the details first.', 'SilentForge is in development. This website does not take orders or collect payments.', '''<h2>Availability and pricing</h2><p>The configurator is a concept tool. It does not reserve parts, confirm stock or create an order. A written quote is required before any future project can be accepted.</p><h2>Shipping and delivery</h2><p>No standard shipping regions, carriers, rates or lead times have been established. A future quote must confirm the delivery destination, battery transport arrangements where applicable, estimated timing and costs.</p><h2>Returns and cancellations</h2><p>No standard retail return or cancellation policy is being offered through this prelaunch site. Any future agreement must state the applicable terms, including treatment of custom work and purchased components, before payment.</p><h2>Warranty and support</h2><p>No product warranty is represented by the concept previews. A future build agreement must state the support scope and any applicable warranty terms. Nothing on this page limits rights that apply under relevant law.</p><h2>Have an existing concern?</h2><p>Email <a href="mailto:trever@barneyglobal.com">trever@barneyglobal.com</a> with the relevant project details. Do not include payment credentials.</p>'''))

add('/privacy/', 'Privacy notice', 'How this development website handles local build configurations and email inquiries.', article('Site information · Updated October 31, 2026', 'Privacy notice.', 'A practical account of the data used by this version of SilentForge.', '''<h2>Website and contact</h2><p>SilentForge is a project by Trever Barney. Questions about this notice or an inquiry can be sent to <a href="mailto:trever@barneyglobal.com">trever@barneyglobal.com</a>.</p><h2>Build configurations</h2><p>The builder stores your selected options, notes and estimates in browser local storage so you can carry a brief to the contact page. That information is not submitted to a database by this site. Use “Clear saved build” on the contact page or your browser’s site-data controls to remove it. A downloaded brief is a file on your device.</p><h2>Contact inquiries</h2><p>The contact form prepares an email link and offers a download of your full inquiry, including the saved build. Long inquiries use a short email draft; you attach the downloaded text file yourself. Opening the prepared link launches your email application. The website does not send a message automatically. If you send it, your email provider and the recipient’s email systems process the message. The information is used to respond and discuss your request.</p><h2>Hosting and external resources</h2><p>The site is hosted on OpenAI Sites. Hosting infrastructure may process request information such as IP address and browser information. Fonts load from Google Fonts, which receives the related network requests. Other external links are visited only when you choose them and are governed by their providers’ notices.</p><h2>Cookies and analytics</h2><p>This version adds no advertising trackers, analytics scripts or application cookies. Hosting or sign-in infrastructure may use its own mechanisms. Local storage for your configuration is separate from cookies.</p><h2>Your choices</h2><p>Avoid including sensitive personal information in build notes. You can browse without saving a configuration, clear local data and contact Trever about access to or deletion of inquiry correspondence. This site does not publish your inquiry.</p>'''))

add('/terms/', 'Website terms', 'Terms for using the SilentForge concept configurator and development website.', article('Site information · Updated October 31, 2026', 'Website terms.', 'These terms describe the current planning website. A future paid project needs a separate written agreement.', '''<h2>Concept planning only</h2><p>Content, illustrations and configurations are provided for exploration. They are not a confirmed bill of materials, engineering certification, quotation or offer to supply an aircraft.</p><h2>Estimates and compatibility</h2><p>Weights, component costs, power and hover estimates are illustrative assumptions. They have not been validated for an assembled aircraft. Do not rely on them for flight operations, purchasing parts or assessing safe performance.</p><h2>Inquiries and future work</h2><p>Submitting or emailing a brief does not form an order or commit either party to work. Scope, pricing, deliverables, delivery, cancellation and support must be agreed separately before any paid work.</p><h2>Responsible use</h2><p>Use the website lawfully and do not interfere with its operation. You are responsible for evaluating your intended application and obtaining appropriate engineering review and operating permissions.</p><h2>Third-party references</h2><p>Component and manufacturer names identify examples. They do not establish endorsement, supply arrangements or a relationship with SilentForge. Linked resources are provided for further reading.</p><h2>Questions and updates</h2><p>The site and these terms may change as the project develops. Contact <a href="mailto:trever@barneyglobal.com">trever@barneyglobal.com</a> with questions. Nothing here is intended to remove rights that cannot be excluded under applicable law.</p>'''))

original = (ROOT / 'original/configurator.html').read_text()
catalog = json.loads((ROOT / 'assets/catalog.json').read_text())
(OUT / 'assets/catalog.js').write_text('globalThis.DroneCatalog = ' + json.dumps(catalog) + ';\n')
selects = []
for key, group in catalog['groups'].items():
    options = ''.join(f'<option value="{o["id"]}">{html.escape(o["label"])}</option>' for o in group['options'])
    selects.append(f'<section class="card"><label for="{key}">{group["label"]}</label><select id="{key}">{options}</select><p class="info" id="{key}Info"></p></section>')
svg = re.search(r'<svg id="droneSvg".*?</svg>', original, re.S).group()
svg = re.sub(r'class="w-full[^"]*"', 'role="img" aria-label="Live top-down drone concept diagram"', svg)
add('/configure/', 'Configure your custom drone', 'Customize a drone concept with itemized parts, compatibility checks and transparent calculations.', (ROOT / 'templates/configure.html').read_text().replace('<!-- OPTIONS -->', ''.join(selects)).replace('<!-- DIAGRAM -->', svg))
add('/review/', 'Review your custom build', 'Review your configuration and estimates before preparing a custom build inquiry.', (ROOT / 'templates/review.html').read_text())
add('/technology/', 'How the drone builder calculates', 'Transparent energy, weight, cost, thrust and battery-current calculations.', article('Calculation guide', 'See what goes into the numbers.', 'A shared calculation engine keeps the builder, downloaded brief, review and contact page consistent.', (ROOT / 'templates/calculations.html').read_text()))

nav = [('/', 'Home'),('/configure/','Configurator'),('/how-it-works/','Process'),('/technology/','Technology'),('/about/','About'),('/contact/','Contact')]
footer_groups = [('Explore',nav[1:4]),('Workshop',[('/about/','About'),('/contact/','Contact & support'),('/faq/','FAQ'),('/safety/','Safety & resources')]),('Information',[('/shipping-returns/','Ordering & delivery'),('/privacy/','Privacy'),('/terms/','Terms')])]
for path,(title,description,body) in pages.items():
    canonical = ORIGIN + path
    links = ''.join(f'<a href="{p}"'+(' aria-current="page"' if path==p else '')+f'>{label}</a>' for p,label in nav)
    footer = ''.join('<div><strong>'+name+'</strong>'+''.join(f'<a href="{p}">{label}</a>' for p,label in group)+'</div>' for name,group in footer_groups)
    scripts = '<script src="/assets/catalog.js" defer></script><script src="/assets/model.js" defer></script><script src="/assets/site.js" defer></script>'
    if path == '/configure/': scripts += '<script src="/assets/three.min.js" defer></script><script src="/assets/builder.js" defer></script>'
    document = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | SilentForge</title><meta name="description" content="{html.escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(title,quote=True)} | SilentForge"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#0b1112"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css">{scripts}</head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><nav class="nav shell" aria-label="Main navigation"><a class="brand" href="/" aria-label="SilentForge home">Silent<span>Forge</span><span aria-hidden="true">.</span></a><button class="menu" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><div class="nav-links" id="navigation">{links}</div></nav></header><main id="main">{body}</main><section class="shell closing"><div><span class="eyebrow">The next step</span><h2>Bring your idea to the workbench.</h2></div><a class="button" href="/contact/">Discuss a build ↗</a></section><footer class="site-footer"><div class="shell"><div class="footer-top"><div><a class="brand" href="/">Silent<span>Forge.</span></a><p class="small">Custom mini drone concepts.<br>A project by Trever Barney.</p><span class="status">In development</span></div>{footer}</div><div class="footer-bottom"><span>© 2026 SilentForge · Trever Barney</span><span>Concept planning · No online orders</span></div></div></footer></body></html>'''
    dest = OUT / path.strip('/') / 'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(document)
(OUT/'404.html').write_text((OUT/'index.html').read_text().replace(pages['/'][2],intro('404 / Page not found','Back to the workbench.', 'This page could not be found. Use the navigation or return home.')+'<div class="shell prose"><a class="button" href="/">Return home</a></div>'))
(OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc></url>' for p in pages)+'</urlset>')
print(f'Built {len(pages)} pages, a 404 page, sitemap and assets in {OUT}')
